const TEST_JWT_SECRET: &str = "test-jwt-secret-32-bytes-long-key!";

/// RAII Guard ensuring background Flask process is terminated when dropped.
struct FlaskProcessGuard {
    child: Child,
    port: u16,
}

impl FlaskProcessGuard {
    async fn spawn(secret: &str) -> Self {
        // Find an open port by binding a temporary TcpListener
        let listener = std::net::TcpListener::bind("127.0.0.1:0").expect("bind ephemeral port");
        let port = listener.local_addr().unwrap().port();
        drop(listener);

        let child = Command::new("python3")
            .arg("backend/app.py")
            .env("PORT", port.to_string())
            .env("HOST", "127.0.0.1")
            .env("SIDECAR_SECRET", secret)
            .stdout(Stdio::null())
            .stderr(Stdio::null())
            .spawn()
            .expect("Failed to spawn Python Flask backend");

        let guard = Self { child, port };
        guard.wait_ready().await;
        guard
    }

    async fn wait_ready(&self) {
        let start = std::time::Instant::now();
        let client = reqwest::Client::builder()
            .timeout(std::time::Duration::from_millis(500))
            .build()
            .unwrap();
        let url = format!("http://127.0.0.1:{}/healthz", self.port);

        while start.elapsed() < std::time::Duration::from_secs(10) {
            if let Ok(res) = client.get(&url).send().await {
                if res.status().is_success() {
                    return;
                }
            }
            tokio::time::sleep(std::time::Duration::from_millis(50)).await;
        }
        panic!(
            "Flask backend failed to respond on port {} within 10 seconds",
            self.port
        );
    }
}

impl Drop for FlaskProcessGuard {
    fn drop(&mut self) {
        let _ = self.child.kill();
        let _ = self.child.wait();
    }
}

#[derive(Debug, Serialize, Deserialize)]
struct PythonVector {
    secret: String,
    timestamp: u64,
    payload_b64: String,
    signature: String,
}

// =============================================================================
// 1. Cross-Language HMAC Parity: Python -> Rust
// =============================================================================

#[tokio::test]
async fn test_cross_language_parity_python_generated_vectors_verified_by_rust() {
    // Generate test vectors using Python's standard hmac + hashlib and verify in Rust crypto
    let script = r#"
import hmac, hashlib, json, base64, sys

vectors = []
cases = [
    ("test-sidecar-secret-32-bytes-long!", 1731000000, b""),
    ("test-sidecar-secret-32-bytes-long!", 1731000000, b"{}"),
    ("test-sidecar-secret-32-bytes-long!", 1731000000, b'{"service":"core"}'),
    ("test-sidecar-secret-32-bytes-long!", 1731000000, b'{"to":"alice@ourcompany.com","body":"Test email"}'),
    ("test-sidecar-secret-32-bytes-long!", 1731000000, "{\"msg\":\"🚀 Unicode 測試 \\u0000 \\n \\t\"}".encode("utf-8")),
    ("test-sidecar-secret-32-bytes-long!", 1731000000, b'{"nested":{"arr":[1,2,3,true,false,null],"key":"val"}}'),
    ("test-sidecar-secret-32-bytes-long!", 1731000000, (b"x" * 65536)),
    ("short", 1731000000, b'{"service":"core"}'),
    ("a" * 128, 1731000000, b'{"service":"core"}'),
    ("special!@#$%^&*()_+~`", 1731000000, b'{"service":"core"}'),
    ("test-sidecar-secret-32-bytes-long!", 0, b"epoch_zero"),
    ("test-sidecar-secret-32-bytes-long!", 2147483647, b"year_2038"),
]

for secret, ts, payload in cases:
    secret_bytes = secret.encode("utf-8")
    signing_input = f"{ts}.".encode("utf-8") + payload
    sig = hmac.new(secret_bytes, signing_input, hashlib.sha256).hexdigest()
    vectors.append({
        "secret": secret,
        "timestamp": ts,
        "payload_b64": base64.b64encode(payload).decode("ascii"),
        "signature": sig,
    })

print(json.dumps(vectors))
"#;

    let output = Command::new("python3")
        .args(["-c", script])
        .output()
        .expect("Failed to execute python generator");

    assert!(output.status.success(), "Python script failed");
    let stdout = String::from_utf8(output.stdout).unwrap();
    let vectors: Vec<PythonVector> = serde_json::from_str(&stdout).unwrap();

    assert!(!vectors.is_empty());
    for vec in &vectors {
        let payload = base64::engine::general_purpose::STANDARD
            .decode(&vec.payload_b64)
            .unwrap();

        // 1. Verify with verify_payload_signature_at (simulating now = timestamp)
        let res = verify_payload_signature_at(
            vec.secret.as_bytes(),
            vec.timestamp,
            &payload,
            &vec.signature,
            vec.timestamp,
            DEFAULT_MAX_SKEW_SECS,
        );
        assert!(
            res.is_ok(),
            "Rust verification failed for Python-generated vector with ts {}: {:?}",
            vec.timestamp,
            res
        );

        // 2. Verify with header string parsing
        let res_hdr = verify_payload_signature_headers_at(
            vec.secret.as_bytes(),
            &vec.timestamp.to_string(),
            &vec.signature,
            &payload,
            vec.timestamp,
            DEFAULT_MAX_SKEW_SECS,
        );
        assert!(
            res_hdr.is_ok(),
            "Rust header verification failed for Python vector: {:?}",
            res_hdr
        );

        // 3. Verify uppercase signature acceptance (constant-time hex equality)
        let res_upper = verify_payload_signature_at(
            vec.secret.as_bytes(),
            vec.timestamp,
            &payload,
            &vec.signature.to_uppercase(),
            vec.timestamp,
            DEFAULT_MAX_SKEW_SECS,
        );
        assert!(
            res_upper.is_ok(),
            "Rust verification failed on uppercase hex: {:?}",
            res_upper
        );
    }
}

