// 2. Cross-Language HMAC Parity: Rust -> Python
// =============================================================================

#[tokio::test]
async fn test_cross_language_parity_rust_generated_signatures_verified_by_python() {
    let test_cases: Vec<(&str, u64, &[u8])> = vec![
        ("test-sidecar-secret-32-bytes-long!", 1731000000, b""),
        ("test-sidecar-secret-32-bytes-long!", 1731000000, b"{}"),
        (
            "test-sidecar-secret-32-bytes-long!",
            1731000000,
            b"{\"service\":\"core\"}",
        ),
        (
            "test-sidecar-secret-32-bytes-long!",
            1731000000,
            b"{\"to\":\"alice@ourcompany.com\",\"body\":\"Secure message.\"}",
        ),
        (
            "test-sidecar-secret-32-bytes-long!",
            1731000000,
            "{\"msg\":\"🚀 Unicode 測試 \\u0000 \\n \\t\"}".as_bytes(),
        ),
        (
            "test-sidecar-secret-32-bytes-long!",
            1731000000,
            b"{\"escaped\":\"line1\\nline2\\t\\\"quotes\\\"\\\\backslash\"}",
        ),
        (
            "test-sidecar-secret-32-bytes-long!",
            1731000000,
            &[0x00, 0x01, 0x02, 0xfe, 0xff],
        ),
        ("short_secret", 1731000000, b"{\"data\":\"short_key_test\"}"),
        (
            "super_long_secret_key_exceeding_sha256_block_size_64_bytes_0123456789abcdef",
            1731000000,
            b"{\"data\":\"long_key_test\"}",
        ),
    ];

    #[derive(Serialize)]
    struct RustVerificationCase {
        secret: String,
        timestamp: u64,
        payload_b64: String,
        signature: String,
    }

    let mut py_input = Vec::new();
    for (secret, ts, payload) in test_cases {
        let sig = sign_payload(secret.as_bytes(), ts, payload);
        py_input.push(RustVerificationCase {
            secret: secret.to_string(),
            timestamp: ts,
            payload_b64: base64::engine::general_purpose::STANDARD.encode(payload),
            signature: sig,
        });
    }

    let json_input = serde_json::to_string(&py_input).unwrap();

    let python_verifier = r#"
import sys, json, base64, hmac, hashlib
from backend.app import create_app

data = json.loads(sys.stdin.read())
for idx, item in enumerate(data):
    secret = item["secret"]
    ts = item["timestamp"]
    payload = base64.b64decode(item["payload_b64"])
    sig = item["signature"]

    # 1. Direct HMAC calculation matching backend/app.py logic
    canonical = f"{ts}.".encode("utf-8") + payload
    expected = hmac.new(secret.encode("utf-8"), canonical, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(sig.lower(), expected.lower()):
        print(f"FAILED direct compare at index {idx}: expected {expected}, got {sig}")
        sys.exit(1)

    # 2. Test inside Flask app request context
    app = create_app(secret=secret)
    client = app.test_client()
    headers = {
        "X-Sidecar-Timestamp": str(ts),
        "X-Sidecar-Signature": sig,
    }
    # For /healthz it should bypass; for /api/v1/system/status with monkeypatched time it must succeed
    import time
    orig_time = time.time
    try:
        time.time = lambda: float(ts) # exact match to prevent skew expiry
        res = client.post("/api/v1/system/status", data=payload, headers=headers)
        if res.status_code != 200:
            print(f"FAILED Flask middleware at index {idx}: status {res.status_code}, data {res.get_data()}")
            sys.exit(1)
    finally:
        time.time = orig_time

print("ALL_PASSED")
"#;

    let mut child = Command::new("python3")
        .args(["-c", python_verifier])
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .expect("Failed to spawn Python verifier");

    use std::io::Write;
    child
        .stdin
        .as_mut()
        .unwrap()
        .write_all(json_input.as_bytes())
        .unwrap();

    let output = child.wait_with_output().unwrap();
    let stdout = String::from_utf8_lossy(&output.stdout);
    let stderr = String::from_utf8_lossy(&output.stderr);

    assert!(
        output.status.success(),
        "Python verifier failed on Rust signatures: stdout: {}, stderr: {}",
        stdout,
        stderr
    );
    assert!(stdout.contains("ALL_PASSED"));
}

// =============================================================================
// 3. Replay Window and Tampering Rejection Parity
// =============================================================================

#[test]
fn test_rejection_parity_tampering_and_skew() {
    let secret = b"shared-sidecar-secret-key-12345";
    let now = 1731000030u64;
    let payload = b"{\"service\":\"core\"}";
    let valid_sig = sign_payload(secret, now, payload);

    // 1. Valid signature at exact time succeeds
    assert_eq!(
        verify_payload_signature_at(secret, now, payload, &valid_sig, now, 30),
        Ok(())
    );

    // 2. Exact 30-second boundary past succeeds
    let past_boundary_sig = sign_payload(secret, now - 30, payload);
    assert_eq!(
        verify_payload_signature_at(secret, now - 30, payload, &past_boundary_sig, now, 30),
        Ok(())
    );

    // 3. Exact 30-second boundary future succeeds
    let future_boundary_sig = sign_payload(secret, now + 30, payload);
    assert_eq!(
        verify_payload_signature_at(secret, now + 30, payload, &future_boundary_sig, now, 30),
        Ok(())
    );

    // 4. Past 31-second boundary fails
    let past_expired_sig = sign_payload(secret, now - 31, payload);
    assert_eq!(
        verify_payload_signature_at(secret, now - 31, payload, &past_expired_sig, now, 30),
        Err(CryptoError::TimestampExpired {
            skew_secs: 31,
            max_skew_secs: 30
        })
    );

    // 5. Future 31-second boundary fails
    let future_expired_sig = sign_payload(secret, now + 31, payload);
    assert_eq!(
        verify_payload_signature_at(secret, now + 31, payload, &future_expired_sig, now, 30),
        Err(CryptoError::TimestampExpired {
            skew_secs: 31,
            max_skew_secs: 30
        })
    );

    // 6. Tampered payload fails
    let tampered_payload = b"{\"service\":\"attacker\"}";
    assert_eq!(
        verify_payload_signature_at(secret, now, tampered_payload, &valid_sig, now, 30),
        Err(CryptoError::SignatureMismatch)
    );

    // 7. Wrong secret fails
    assert_eq!(
        verify_payload_signature_at(b"wrong-secret-key", now, payload, &valid_sig, now, 30),
        Err(CryptoError::SignatureMismatch)
    );
}

